/**
 * SettingsReadRequest asks for the settings of one target. Project is empty
 * for the global config file.
 */
export interface SettingsReadRequest {
  project?: string;
}
/**
 * SettingsReadResponse is the registry entries that apply to a target, with
 * their current values.
 */
export interface SettingsReadResponse {
  /**
   * Project is nil for a global read.
   */
  project?: SettingsProject;
  entries: SettingsEntry[];
  /**
   * PendingRestart lists the startup-only keys changed since the server started.
   */
  pending_restart?: string[];
  /**
   * Categories is the page tree for the target: categories, sections and
   * groups in page order. One holding no entry of the read is absent.
   */
  categories: SettingsCategory[];
  /**
   * Redirects maps a retired section slug to the slug that now holds its keys.
   */
  redirects: { [key: string]: string};
  /**
   * NotificationKinds is the notification catalog in row order. The page
   * reads it here, never from a copy in TypeScript. Only the global read
   * carries it (and NotificationChannels): a project may not set the lists.
   */
  notification_kinds: NotificationKind[];
  /**
   * NotificationChannels are the five channels in display order.
   */
  notification_channels: NotificationChannel[];
}
/**
 * NotificationChannel is one channel with the config keys of its switch and
 * kind list.
 */
export interface NotificationChannel {
  id: string;
  label: string;
  switch_key: string;
  list_key: string;
  /**
   * Section is the settings section page of the channel's own options.
   * Empty for a channel with none (Web toast).
   */
  section: string;
}
/**
 * NotificationKind is one row of the notification catalog.
 */
export interface NotificationKind {
  id: string;
  name: string;
  hint: string;
  default: boolean;
}
/**
 * SettingsCategory is one category of the page tree and its sections.
 */
export interface SettingsCategory {
  name: string;
  sections: SettingsSection[];
}
/**
 * SettingsSection is one section of the page tree and its groups.
 */
export interface SettingsSection {
  name: string;
  slug: string;
  groups: SettingsGroup[];
}
/**
 * SettingsGroup is one group of a section. A Table group renders its entries
 * as a grid of tier rows and column columns.
 */
export interface SettingsGroup {
  name: string;
  table?: boolean;
}
/**
 * SettingsProject is a project's identity and the facts the page shows
 * beside its settings.
 */
export interface SettingsProject {
  name: string;
  repo?: string;
  vcs?: string;
  /**
   * RepoChecksFile: the repo holds .gx/checks.json, which wins over the
   * project's checks.
   */
  repo_checks_file: boolean;
}
/**
 * SettingsEntry is one setting: what it is and what the target's file holds.
 */
export interface SettingsEntry {
  /**
   * Key is the display key path; Path is its segments.
   */
  key: string;
  path: string[];
  type: string;
  section: string;
  category: string;
  group: string;
  /**
   * Tier and Column place a key of a table group (Models) in its table.
   */
  tier?: string;
  column?: string;
  description: string;
  enum?: string[];
  min?: number /* float64 */;
  integer?: boolean;
  restart?: boolean;
  risky?: boolean;
  confirm_text?: string;
  read_only?: boolean;
  /**
   * Identity marks an entry that names the project (name, repo, vcs).
   */
  identity?: boolean;
  /**
   * Label replaces the name derived from the key path.
   */
  label?: string;
  /**
   * RiskyOffOnly: only turning the value off (or resetting it) asks to confirm.
   */
  risky_off_only?: boolean;
  /**
   * Override is how a project row relates to its global key: "cap",
   * "follows-global", or absent for a value that replaces the global one.
   */
  override?: string;
  /**
   * Notice is a warning the page shows under the row, such as a removed value
   * that is read as another.
   */
  notice?: string;
  /**
   * Set: the target's file holds the key. Absent means the default (or the
   * global value, in a project) applies.
   */
  set: boolean;
  /**
   * Value is the file's value; never sent for a secret.
   */
  value?: unknown;
  /**
   * Default is the built-in default, when the key has one.
   */
  default?: unknown;
  /**
   * GlobalKey and GlobalValue are, in a project read, the global key the
   * entry overrides or caps and that key's current effective value.
   */
  global_key?: string;
  global_value?: unknown;
}
/**
 * SettingChange sets Key to Value, or removes Key when Remove is set. Key is
 * the display key path (SettingsEntry.Key).
 */
export interface SettingChange {
  key: string;
  value?: unknown;
  remove?: boolean;
}
/**
 * SettingsWriteRequest applies Changes together or not at all. Project is
 * empty for the global config file.
 */
export interface SettingsWriteRequest {
  project?: string;
  changes: SettingChange[];
}
/**
 * SettingsWriteResult says what a write did. A refusal is a result: it names
 * the failing keys, and nothing was written.
 */
export interface SettingsWriteResult {
  refused?: boolean;
  keys?: string[];
  reason?: string;
  /**
   * Values holds each changed key's saved value; null for a removed key.
   */
  values?: { [key: string]: unknown};
  /**
   * RestartNeeded lists the startup-only keys that wait for a restart.
   */
  restart_needed?: string[];
  /**
   * Notices are messages to show after the save, such as the harness switch.
   */
  notices?: string[];
}

